def find_numbers(x):
    # Since a ^ b = (a + b) / 2, we can derive that a and b must have the same number of 1s in their binary representation.
    # This means a and b must be of the form 2^k + x and 2^k - x for some k.
    # We need to find such k such that both a and b are positive and within the given range.

    # Start with the smallest possible k
    k = 1
    while True:
        a = 2**k + x
        b = 2**k - x
        if a > 0 and b > 0 and a < 2**32 and b < 2**32:
            return (a, b)
        k += 1
        # If k is too large, it means no such pair exists
        if k > 32:
            return -1

